<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileBirthdateAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileBirthdateAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileBirthdateAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getBirthdate returns null on a freshly created holder.
     */
    public function testBirthdateNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileBirthdateAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isBirthdateAssigned());
        $this->assertNull($holder->getBirthdate());
    }
}
class ImplWithUserProfileBirthdateAttributeHolderUnitTest
{
    use UserProfileBirthdateAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedBirthdateRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultBirthdate();
    }
}
